#include "Halide.h"
#include "wrapper.h"   // generated by ../generator into build/
#include <chrono>
#include <iostream>

int main()
{
    Halide::Buffer<double> b_A(120, 120, 120), b_B(120, 120, 120);

    for (int x = 0; x < 120; x++)
        for (int y = 0; y < 120; y++)
            for (int z = 0; z < 120; z++)
            {
                b_A(x, y, z) = (x + y + z) % 10;
                b_B(x, y, z) = (x * y + z) % 10;
            }

    auto start = std::chrono::steady_clock::now();
    function_heat3d_LARGE(b_A.raw_buffer(), b_B.raw_buffer());
    auto end = std::chrono::steady_clock::now();

    std::cout << std::chrono::duration<double, std::milli>(end - start).count()
              << " ms" << std::endl;
    return 0;
}